ap = argparse.ArgumentParser()
ap.add_argument("--out", required=True); ap.add_argument("--part", default="all", choices=["colab", "pc", "all"])
ap.add_argument("--tier", default="1", choices=["1", "2", "all"]); ap.add_argument("--jobs", type=int, default=os.cpu_count() or 2)
ap.add_argument("--hours", type=float, default=0, help="stop after this many hours (0 = run to the end)")
