a = ap.parse_args()
OUT = os.path.abspath(a.out); os.makedirs(OUT, exist_ok=True)
W = os.path.abspath(a.work or ("/content/acc_cov" if os.path.isdir("/content") else os.path.expanduser("~/.cache/acc_cov")))
os.makedirs(W, exist_ok=True); REPO = os.getcwd()
def sh(c): print("+", c, flush=True); subprocess.run(c, shell=True, check=True, cwd=W)
if not os.path.isdir(W + "/sair/competition"):
    sh("git clone -q https://github.com/SAIRcompetition/Andrews-Curtis sair && cd sair && git checkout -q a0fd6e6f52d82c93ccc06ab91d81e8fa3678256e")
for n, b in SRC.items(): open(W + "/" + n, "wb").write(base64.b64decode(b))
sh("gcc -O3 -o acc_opt acc_opt.c -lm && gcc -O3 -o acc_beam acc_beam.c -lm && gcc -O3 -o acc_window acc_window.c -lm")
if not os.path.exists(W + "/T8.tab"):
    os.makedirs(W + "/tbw", exist_ok=True); sh("./acc_opt tball 8 32000000 T8.tab tbw")
tg = (TIER1 if a.tier == "1" else TIER2 if a.tier == "2" else TIER1 + TIER2)
tg = [t for i, t in enumerate(tg) if a.part == "all" or (i % 2 == 0) == (a.part == "colab")]
J = max(1, min(a.jobs, len(tg)))
print("targets %d (tier %s, part %s) on %d workers; results in %s" % (len(tg), a.tier, a.part, J, OUT), flush=True)
procs = []
for j in range(J):
    mine = [{"id": t[0], "record": t[1], "k": t[2]} for t in tg[j::J]]
    tf = "%s/targets_%s_%s_%d.json" % (W, a.part, a.tier, j); json.dump(mine, open(tf, "w")); os.makedirs("%s/w%d" % (W, j), exist_ok=True)
    procs.append(subprocess.Popen([sys.executable, W + "/run_beam.py", W + "/sair", W, W + "/T8.tab", "%s/w%d" % (W, j), a.width, "600",
                                   "%s/results_%s_%d.jsonl" % (OUT, a.part, j), tf], cwd=W))
def collect():
    lines, n, hit = [], 0, 0
    for f in sorted(os.listdir(OUT)):
        if f.startswith("results_") and f.endswith(".jsonl"):
            for l in open(OUT + "/" + f):
                r = json.loads(l); n += 1
                if r.get("verdict") in ("TIE", "BEAT"): hit += 1
                for kind in ("ac", "sac"):
                    if r.get(kind): lines.append("%s-%s: [%s]  # %s len %d, AC record %d\n" % (kind, r["id"][3:], ",".join(map(str, r[kind])), r.get("verdict"), len(r[kind]), r["record"]))
    open("%s/LINES_COVERAGE_%s.txt" % (OUT, a.part), "w").write("# coverage run; every line passed the official core; UPG-H checks them against the live board\n" + "".join(lines))
    print("[%s] rows done %d, at/under record %d, lines %d" % (time.strftime("%H:%M"), n, hit, len(lines)), flush=True)
    if a.git_push:
        subprocess.run("git add %s && git commit -q -m 'acc: coverage run progress (%s) [skip ci]' && git push -q origin HEAD" % (OUT, a.part), shell=True, cwd=REPO)
t0, last = time.time(), time.time()
while any(p.poll() is None for p in procs):
    time.sleep(60)
    if time.time() - last > 1200: collect(); last = time.time()
    if a.hours and time.time() - t0 > a.hours * 3600:
        for p in procs: p.kill()
        print("time limit reached; rerun to resume", flush=True); break
collect()
